{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Cefuroxime axetil, a cephem ester prodrug sharing the 3-carbamoyloxymethyl and carboxyl-ester prodrug motif, has mean absolute oral bioavailability of 64% in humans, with other studies reporting 30-52%, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Pivampicillin, an acyloxymethyl ester prodrug of a beta-lactam, has absolute oral bioavailability of 82% (tablet) and 89% (capsule) in humans, demonstrating that this ester prodrug strategy can yield high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Faropenem, a beta-lactam with oral bioavailability of 72-84% in children, supports the ability of beta-lactam cores to be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DZ-2640, an oral carbapenem pivaloyloxymethyl ester prodrug, has human bioavailability at least greater than 30%, supporting high F for beta-lactam ester prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cefditoren, as the cephalosporin ester prodrug cefditoren pivoxil, has absolute oral bioavailability of only about 14% under fasting conditions, providing a lower-similarity contradictory example of a cephalosporin ester prodrug falling below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acetoxymethyl ester prodrug of a cephem beta-lactam. The most transferable evidence—cefuroxime axetil (F 30-64%), pivampicillin (50-89%), faropenem (72-84%), and DZ-2640 (>30%)—supports F >= 20%. A lower-similarity cefditoren record (14%) is a contradictory outlier but does not outweigh the closer analogues.",
  "evidence_gaps": [
    "No direct human or animal F measurement exists for the exact query ester.",
    "The absorption and hydrolysis behavior of the acetoxymethyl ester relative to the 1-acetoxyethyl ester in cefuroxime axetil is uncertain.",
    "The 7-hydroxyethyl substituent is not represented in the closest high-F analogues, so its effect on permeability is uncertain.",
    "Cefditoren shows that some cephalosporin ester prodrugs can fall below 20%, but its lower structural similarity limits transferability."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C02"],
      "decision_effect": "strengthened",
      "direction": "supportive",
