      "family": "pivampicillin"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C21"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "faropenem"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "oral carbapenem prodrug"
    },
    {
      "applicability": "low",
      "card_ids": ["C19"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "cefditoren pivoxil"
    }
  ],
  "revision_action": "initial"
}

